package com.ruoyi.medical.persistence;
import javax.sql.DataSource;
import org.springframework.context.annotation.*;
import org.springframework.boot.autoconfigure.condition.ConditionalOnProperty;
import org.springframework.beans.factory.annotation.Qualifier;
import com.ruoyi.medical.persistence.mapper.SourceReadMapper;
/** Explicit production dependencies. No fallback provider, credential, price, package, or receipt. */
@Configuration(proxyBeanMethods=false)
@ConditionalOnProperty(prefix="medical.formal-evaluation-execution",name="enabled",havingValue="true",matchIfMissing=false)
public class FormalEvaluationInvocationConfiguration {
 @Bean FormalEvaluationInvocationRecords formalEvaluationInvocationRecords(DataSource data,FormalInvocationSchema schema,FormalEvaluationInvocationObjects objects){return new FormalEvaluationInvocationRecords(data,schema,objects);}
 @Bean FormalEvaluationInvocationContext formalEvaluationInvocationContext(DataSource data,ModelConfigurationService models,ModelEligibilityAuthority eligibility,AgentExecutionPolicyAuthority policies,ResourceReadAuthority resources,SourceReadAuthority sources,SourceReadMapper rows,DependencyLineage lineage,FormalCapabilityIdentityAuthority capabilities,RunTokenAuthoritySchema runtime,RuntimeRetentionAuthority retention,@Qualifier("formalInvocationObjectTransport")RuntimeObjectTransport transport,FormalInvocationSchema schema,PermissionSchema json){return new FormalEvaluationInvocationContext(data,models,eligibility,policies,resources,sources,rows,lineage,capabilities,runtime,retention,transport,schema,json);}
 @Bean(name="formalEvaluationInvocationGateway") TaskInvocationLocalBridge formalEvaluationInvocationGateway(org.springframework.core.env.Environment e){String p="medical.formal-evaluation-execution.gateway.";return new TaskInvocationLocalBridge(new TaskInvocationLocalBridge.Configuration(java.nio.file.Path.of(e.getRequiredProperty(p+"executable")),e.getRequiredProperty(p+"executable-sha256"),java.nio.file.Path.of(e.getRequiredProperty(p+"entrypoint")),e.getRequiredProperty(p+"entrypoint-sha256"),java.nio.file.Path.of(e.getRequiredProperty(p+"package-root")),java.nio.file.Path.of(e.getRequiredProperty(p+"package-manifest")),e.getRequiredProperty(p+"package-manifest-sha256"),java.nio.file.Path.of(e.getRequiredProperty(p+"private-configuration")),java.time.Duration.ofSeconds(Long.parseLong(e.getRequiredProperty(p+"timeout-seconds")))));}
 @Bean FormalEvaluationInvocationSchema formalEvaluationInvocationSchema()throws Exception{return new FormalEvaluationInvocationSchema();}
 @Bean FormalEvaluationInvocationObjects formalEvaluationInvocationObjects(DataSource data,PermissionSchema json,FormalInvocationSchema schema,FormalEvaluationInvocationSchema exact,DependencyManifestSchema manifests){return new FormalEvaluationInvocationObjects(data,json,schema,exact,manifests);}
 @Bean FormalEvaluationInvocationHistory formalEvaluationInvocationHistory(DataSource data,FormalEvaluationInvocationRecords records,FormalInvocationSchema schema,FormalInvocationSettlement settlement,FormalInvocationObjectRegistration objects,FormalProviderCaptureEvidence captures,FormalEvaluationToolReceipts tools)throws Exception{return new FormalEvaluationInvocationHistory(data,records,schema,new TaskInvocationResults(data,null,settlement,objects,captures,schema),tools);}
 @Bean FormalEvaluationInvocationService formalEvaluationInvocationService(DataSource data,FormalEvaluationInvocationContext contexts,FormalEvaluationInvocationRecords records,FormalEvaluationSupervisor supervisors,FormalInvocationOutcomeAuthority outcomes,FormalInvocationSourceOriginals originals,FormalInvocationReservations reservations,FormalInvocationDispatch dispatch,FormalInvocationReceiptObjects receipts,FormalInvocationSettlement settlement,FormalInvocationObjectRegistration objects,FormalProviderCaptureEvidence captures,FormalInvocationSchema schema,@Qualifier("formalEvaluationInvocationGateway")TaskInvocationLocalBridge gateway,FormalEvaluationInvocationObjects exactObjects,@Qualifier("formalInvocationObjectTransport")RuntimeObjectTransport transport,FormalEvaluationInvocationHistory histories,FormalTokenizerRunner tokenizer,DependencyLineage lineage,SourceReadMapper sourceRows)throws Exception{return new FormalEvaluationInvocationService(data,contexts,records,supervisors,outcomes,originals,reservations,dispatch,receipts,settlement,objects,captures,schema,gateway,exactObjects,transport,histories,tokenizer,lineage,sourceRows);}
}
